    ```java
    private void checkForMixedNinePatches(@NonNull Context context) {
        List<File> resourceFolders = context.getProject().getResourceFolders();
        for (File resDir : resourceFolders) {
            File[] drawables = resDir.listFiles(file -> file.isDirectory() && file.getName().startsWith("drawable"));
            if (drawables == null) continue;
            for (File drawableDir : drawables) {
                Map<String, File> baseNameToPng = new HashMap<>();
                Map<String, File> baseNameTo9Png = new HashMap<>();
                File[] files = drawableDir.listFiles();
                if (files == null) continue;
                for (File f : files) {
                    String name = f.getName();
                    if (name.endsWith(".9.png")) {
                        String base = name.substring(0, name.length() - 6);
                        baseNameTo9Png.put(base, f);
                    } else if (name.endsWith(".png")) {
                        String base = name.substring(0, name.length() - 4);
                        baseNameToPng.put(base, f);
                    }
                }
                for (String base : baseNameToPng.keySet()) {
                    if (baseNameTo9Png.containsKey(base)) {
                        File pngFile = baseNameToPng.get(base);
                        File ninePatchFile = baseNameTo9Png.get(base);
                        String msg = String.format(
                            "Both `%s` and `%s` exist. They will map to the same drawable resource `@drawable/%s`.",
                            pngFile.getName(), ninePatchFile.getName(), base);
                        context.report(ISSUE, Location.create(pngFile), msg);
                    }
                }
            }
        }
    }
