import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.SourceCodeScanner;
import com.android.tools.lint.detector.api.XmlContext;
import com.intellij.psi.PsiMethod;
import com.intellij.psi.PsiParameter;
import com.intellij.psi.PsiType;
import org.jetbrains.uast.UClass;
import org.w3c.dom.Attr;

import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.android.SdkConstants.ATTR_ON_CLICK;
import static com.android.SdkConstants.VIEW_CLASS;

public class OnClickDetector extends LayoutDetector implements SourceCodeScanner {

    public static final Issue ISSUE = Issue.create(
            "OnClick",
            "onClick method does not exist",
            "The `onClick` attribute value should be the name of a method in this View's context " +
            "to invoke when the view is clicked. This name must correspond to a public method " +
            "that takes exactly one parameter of type `View`.",
            Category.CORRECTNESS,
            5,
            Severity.ERROR,
            new Implementation(OnClickDetector.class, Scope.ALL_RESOURCES_AND_JAVA) // or appropriate scope
    );

    private final Map<String, Location> mRequired = new HashMap<>();
    private final Set<String> mFound = new HashSet<>();

    @NonNull
    @Override
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(ATTR_ON_CLICK);
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String value = attribute.getValue();
        if (value != null && !value.isEmpty()) {
            mRequired.put(value, context.getLocation(attribute));
        }
    }

    @Nullable
    @Override
    public List<String> applicableSuperClasses() {
        return null; // Visit all classes
    }

    @Override
    public void visitClass(@NonNull JavaContext context, @NonNull UClass declaration) {
        for (PsiMethod method : declaration.getMethods()) {
            if (method.hasModifierProperty("public") && !method.hasModifierProperty("static")) {
                PsiParameter[] parameters = method.getParameterList().getParameters();
                if (parameters.length == 1) {
                    PsiType type = parameters[0].getType();
                    if (VIEW_CLASS.equals(type.getCanonicalText()) ||
                        "android.view.View".equals(type.getCanonicalText())) {
                        mFound.add(method.getName());
                    }
                }
            }
        }
    }

    @Override
    public void afterCheckRootProject(@NonNull Context context) {
        for (Map.Entry<String, Location> entry : mRequired.entrySet()) {
            if (!mFound.contains(entry.getKey())) {
                context.report(ISSUE, entry.getValue(),
                        "Corresponding method handler '`" + entry.getKey() + "(android.view.View)`' not found");
            }
        }
        mRequired.clear();
        mFound.clear();
    }
}
