import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import java.util.Collection;
import java.util.Collections;

public class ResourcePrefixDetector extends Detector implements XmlScanner, BinaryResourceScanner {
    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "In Gradle projects you can specify a resource prefix that all resources " +
            "in the project must conform to. This makes it easier to ensure that you don't " +
            "accidentally combine resources from different libraries, since they all end " +
            "up in the same shared app namespace.",
            Category.CORRECTNESS,
            7,
            Severity.FATAL,
            new Implementation(ResourcePrefixDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private String prefix;

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList("*");
    }

    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        prefix = context.getProject().getResourcePrefix();
    }

    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        prefix = null;
    }

    @Override
    public void beforeCheckFile(@NonNull Context context) {
        // Could be used to initialize per-file state, but we'll keep it simple.
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (prefix == null || prefix.isEmpty()) return;

        // Check if it's a values file
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == ResourceFolderType.VALUES) {
            String name = element.getAttribute("name");
            if (name != null && !name.isEmpty()) {
                if (!name.startsWith(prefix)) {
                    context.report(ISSUE, element, context.getLocation(element),
                            "Resource name `" + name + "` does not start with required prefix `" + prefix + "`");
                }
            }
        } else {
            // For non-values XML files, only check the root element to avoid duplicate reports
            if (element.getParentNode() == null || element.getParentNode().getNodeType() == org.w3c.dom.Node.DOCUMENT_NODE) {
                String fileName = context.file.getName();
                int dotIndex = fileName.lastIndexOf('.');
                String resourceName = dotIndex != -1 ? fileName.substring(0, dotIndex) : fileName;
                if (!resourceName.startsWith(prefix)) {
                    context.report(ISSUE, element, context.getLocation(element),
                            "Resource file name `" + fileName + "` does not start with required prefix `" + prefix + "`");
                }
            }
        }
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return true;
    }

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context) {
        if (prefix == null || prefix.isEmpty()) return;

        String fileName = context.file.getName();
        int dotIndex = fileName.lastIndexOf('.');
        String resourceName = dotIndex != -1 ? fileName.substring(0, dotIndex) : fileName;

        if (!resourceName.startsWith(prefix)) {
            context.report(ISSUE, Location.create(context.file),
                    "Resource file name `" + fileName + "` does not start with required prefix `" + prefix + "`");
        }
    }
}
