   @Override
   public void beforeCheckFile(@NonNull Context context) {
       optionalFeatures = new HashSet<>();
       if (context instanceof XmlContext) {
           Document document = ((XmlContext) context).document;
           if (document != null) {
               NodeList features = document.getElementsByTagName("uses-feature");
               for (int i = 0; i < features.getLength(); i++) {
                   Node node = features.item(i);
                   if (node instanceof Element) {
                       Element el = (Element) node;
                       String required = el.getAttributeNS("http://schemas.android.com/apk/res/android", "required");
                       if ("false".equals(required)) {
                           String name = el.getAttributeNS("http://schemas.android.com/apk/res/android", "name");
                           if (!name.isEmpty()) {
                               optionalFeatures.add(name);
                           }
                       }
                   }
               }
           }
       }
   }
   ```

