    public void afterCheckRootProject(@NonNull Context context) {
        if (arrays == null) return;

        for (Map.Entry<String, List<ArrayRecord>> entry : arrays.entrySet()) {
            List<ArrayRecord> records = entry.getValue();
            if (records.size() < 2) {
                continue;
