                       break;
                   }
               }
               child = child.getNextSibling();
           }

           if (hasWeight) {
               context.report(ISSUE_BASELINE, element, context.getLocation(element),
                   "Set android:baselineAligned=\"false\" on this element for better performance");
           }
       }
   }
