                                   }
                               }
                           }
                           child = XmlUtils.getNextTag(child)
                       }
                       if (hasAction) {
                           activities.add(ActivityInfo(packageName, true, hasCategory))
                       }
                       intentFilter = XmlUtils.getNextTagByName(intentFilter, TAG_INTENT_FILTER)
                   }
               }
           }
       }

