                           "Configuration activity for WATCH_FACE_EDITOR must include category com.google.android.wearable.watchface.category.WEARABLE_CONFIGURATION for minSdkVersion < 30"
                       )
                   }
               }
           }
           services.clear()
           activities.clear()
       }

