   }

   @Override
   public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression node, @NonNull PsiMethod method) {
       String className = method.getContainingClass().getQualifiedName();
       if (("java.lang.System".equals(className) || "java.lang.Runtime".equals(className))
               && method.getParameterList().getParametersCount() == 1) {
           context.report(ISSUE, node, context.getLocation(node),
                   "Native code should be placed in the library directory; " +
                   "use System.loadLibrary() instead of System.load() to avoid " +
                   "loading native code from unsafe locations.");
       }
   }

   @Override
   public void afterCheckEachProject(@NonNull Context context) {
       // No project-level aggregation needed; issues are reported per call.
   }
