      @Override
      public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
          String fileName = context.file.getName();
          if (!fileName.endsWith(".xml")) return;
          String layoutName = fileName.substring(0, fileName.length() - 4); // remove .xml

          String qualifier = context.getConfiguration().getQualifierString();
          if (qualifier == null || qualifier.isEmpty()) {
              qualifier = "default";
          }

          Set<String> ids = new HashSet<>();
          collectIds(document.getDocumentElement(), ids);

          layoutIds.computeIfAbsent(layoutName, k -> new HashMap<>())
                   .put(qualifier, ids);
      }

      private void collectIds(Element element, Set<String> ids) {
          String id = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_ID);
          if (id != null && !id.isEmpty()) {
              // id is like @+id/myId or @id/myId
              int slash = id.indexOf('/');
              if (slash != -1 && slash + 1 < id.length()) {
                  ids.add(id.substring(slash + 1));
              }
